// Dev-time only: fetches the Public Suffix List and writes src/core/psl-data.js.
// The shipped extension never touches the network; it only imports the generated file.
import { writeFile } from 'node:fs/promises';
import { domainToASCII } from 'node:url';
import { fileURLToPath } from 'node:url';

const SOURCE = 'https://publicsuffix.org/list/public_suffix_list.dat';
const OUT = fileURLToPath(new URL('../src/core/psl-data.js', import.meta.url));

const res = await fetch(SOURCE);
if (!res.ok) throw new Error(`Fetch failed: ${res.status} ${res.statusText}`);
const text = await res.text();

const rules = new Set();
for (const raw of text.split(/\r?\n/)) {
  const line = raw.trim();
  if (!line || line.startsWith('//')) continue;
  // Rules end at the first whitespace; both ICANN and PRIVATE sections are kept
  // because Chrome's cookie code treats private suffixes (github.io) as suffixes too.
  const rule = line.split(/\s+/)[0].toLowerCase();
  const prefix = rule.startsWith('!') ? '!' : rule.startsWith('*.') ? '*.' : '';
  const ascii = domainToASCII(rule.slice(prefix.length));
  if (!ascii) {
    console.warn(`Skipping unconvertible rule: ${rule}`);
    continue;
  }
  rules.add(prefix + ascii);
}

const list = [...rules].sort();
const header = [
  '// Generated by scripts/build-psl.mjs. Do not edit.',
  `// Source: ${SOURCE}`,
  `// Fetched: ${new Date().toISOString()}`,
  `// Rules: ${list.length} (ICANN + PRIVATE, punycode, "*." wildcards, "!" exceptions)`,
].join('\n');

await writeFile(OUT, `${header}\nexport const RULES = ${JSON.stringify(list.join('\n'))};\n`);
console.log(`Wrote ${list.length} rules to ${OUT}`);
